from __future__ import annotations
import base64, hashlib, subprocess, sys, tempfile, zlib
from pathlib import Path
PATCH_SHA256="e19349fe4613bb66ac088aee73f63f9a2cea75c3aaa187cf362f5039438f16b4"
PATCH_BASE64=""""""
def main():
    if len(sys.argv)!=2: raise SystemExit("Kullanım: apply_mizan_observation_round.py <source-root>")
    root=Path(sys.argv[1]).resolve()
    patch=zlib.decompress(base64.b64decode(PATCH_BASE64))
    if hashlib.sha256(patch).hexdigest()!=PATCH_SHA256: raise SystemExit("Patch SHA uyuşmuyor")
    with tempfile.NamedTemporaryFile(suffix=".patch") as f:
        f.write(patch); f.flush()
        subprocess.run(["patch","--batch","--forward","-p1","-i",f.name],cwd=root,check=True)
    required={
      "lib/screens/expenses_screen.dart":["Günlük harcamalar","Ödemeler","Bütün harcamalar"],
      "lib/screens/reports_screen.dart":["Seçili dönemde ödemelere yapılan gider","Kişi bazında güncel kalan borç"],
      "lib/screens/people_screen.dart":["gün gecikmede","Kalan toplam ayrıntısı"],
      "test/csv_empty_merge_duplicate_test.dart":["duplicateCount"],
      "test/overdue_aggregate_regression_test.dart":["12600"],
    }
    missing=[]
    for rel,tokens in required.items():
      text=(root/rel).read_text(encoding="utf-8")
      for token in tokens:
        if token not in text: missing.append(f"{rel}:{token}")
    if missing: raise SystemExit(f"Eksik kapsam: {missing}")
    print("MİZAN kullanıcı gözlem turu uygulandı.")
if __name__=="__main__": main()
